mapper.select:
SELECT c.id as candidateId, c.real_name as realName, c.identity_num as identityNum, c.mobile as mobile, c.sex as sex, c.email as email, c.birthday as birthday, c.created_time as createTime, c.job_id as job_id, c.school AS school, c.major AS major, c.certificate AS certificate, c.awards AS awards, c.experiment AS experiment, c.introduce AS introduce, j.job_name as jobName
FROM candidate c LEFT JOIN job j ON c.job_id = j.id
AND c.real_name = #{paramMap.realName}
AND c.mobile = #{paramMap.mobile}
ORDER BY c.created_time DESC
